import{_ as a,C as s,o as i,c as o,j as t,a as r,E as d,a2 as c}from"./chunks/framework.D4CBuebE.js";const y=JSON.parse('{"title":"Connect a machine","description":"Connect the computer your agents will run on, in one command.","frontmatter":{"title":"Connect a machine","description":"Connect the computer your agents will run on, in one command."},"headers":[],"relativePath":"guide/connect-a-machine.md","filePath":"guide/connect-a-machine.md","lastUpdated":1790930293000}'),h={name:"guide/connect-a-machine.md"};function l(p,e,u,m,g,k){const n=s("TutorialVideo");return i(),o("div",null,[e[0]||(e[0]=t("h1",{id:"connect-a-machine",tabindex:"-1"},[r("Connect a machine "),t("a",{class:"header-anchor",href:"#connect-a-machine","aria-label":'Permalink to "Connect a machine"'},"​")],-1)),d(n,{n:"01"}),e[1]||(e[1]=c('<p>Agents run on your own machines, never on ours. A machine you connect is called a <strong>runner</strong>.</p><p>The machine needs Node.js (for <code>npx</code>), the repository cloned, and at least one coding agent installed and signed in: Claude Code, Codex, OpenCode or Gemini CLI. The runner finds them by itself, and each ticket can pick any agent its machine has.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><p>Open a terminal <strong>in a repository&#39;s folder</strong> — the one you cloned, not your home folder.</p></li><li><p>Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tackora@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>It prints a link and an 8-character code.</p></li><li><p>Open the link (or go to <strong>Runners</strong> and type the code). Check the code is the one your terminal shows, then press <strong>Connect</strong>.</p></li><li><p>The terminal says <strong>Waiting for work</strong> and the machine appears on the Runners page with its repository. Leave it running.</p></li></ol><h2 id="more-repositories-on-the-same-machine" tabindex="-1">More repositories on the same machine <a class="header-anchor" href="#more-repositories-on-the-same-machine" aria-label="Permalink to &quot;More repositories on the same machine&quot;">​</a></h2><p>In each repository&#39;s folder, in another terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tackora@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span></span></code></pre></div><p>The running runner picks it up within 15 seconds; no restart. <code>npx tackora@latest remove</code> in a folder stops working on that repository (its files stay as they are).</p><h2 id="keep-it-running-in-the-background" tabindex="-1">Keep it running in the background <a class="header-anchor" href="#keep-it-running-in-the-background" aria-label="Permalink to &quot;Keep it running in the background&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tackora@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>The runner then starts when you log in and restarts if it stops (a systemd user service on Linux, a scheduled task on Windows). Connect the machine with <code>start</code> first. <code>service uninstall</code> removes it; <code>service status</code> shows it.</p><h2 id="all-commands" tabindex="-1">All commands <a class="header-anchor" href="#all-commands" aria-label="Permalink to &quot;All commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>start</code></td><td>Connect this machine (signing in the first time) and run its tickets. Run inside a repository, it also adds that one. Ctrl+C stops it and its agents.</td></tr><tr><td><code>add [folder]</code></td><td>Work on one more repository. A running <code>start</code> picks it up within 15 seconds.</td></tr><tr><td><code>remove [folder]</code></td><td>Stop working on a repository. Its folder stays as it is.</td></tr><tr><td><code>status</code></td><td>What this machine is set up for: its repositories and the agents it found.</td></tr><tr><td><code>service install</code></td><td>Run <code>start</code> in the background from login on. <code>service uninstall</code> removes it, <code>service status</code> shows it.</td></tr><tr><td><code>--version</code></td><td>Which runner version this is.</td></tr></tbody></table>',13))])}const C=a(h,[["render",l]]);export{y as __pageData,C as default};
